add_action( 'woocommerce_product_options_general_product_data', 'perfectpixel_custom_badge_fields' );
add_action( 'woocommerce_admin_process_product_object', 'perfectpixel_custom_badge_save' );
add_action( 'woocommerce_single_product_summary', 'perfectpixel_custom_badge_output', 3 );

function perfectpixel_custom_badge_fields() {
	echo '<div class="options_group">';
	woocommerce_wp_checkbox( array( 'id' => '_perfectpixel_badge', 'label' => 'Εμφάνιση ετικέτας' ) );
	woocommerce_wp_text_input( array( 'id' => '_perfectpixel_badge_text', 'label' => 'Κείμενο ετικέτας', 'placeholder' => '{{custom_badge_default}}' ) );
	echo '</div>';
}

function perfectpixel_custom_badge_save( $product ) {
	$product->update_meta_data( '_perfectpixel_badge', isset( $_POST['_perfectpixel_badge'] ) ? 'yes' : 'no' );
	$text = isset( $_POST['_perfectpixel_badge_text'] ) ? sanitize_text_field( wp_unslash( $_POST['_perfectpixel_badge_text'] ) ) : '';
	$product->update_meta_data( '_perfectpixel_badge_text', $text );
}

function perfectpixel_custom_badge_output() {
	global $product;
	if ( ! $product || 'yes' !== $product->get_meta( '_perfectpixel_badge' ) ) {
		return;
	}
	$text  = $product->get_meta( '_perfectpixel_badge_text' );
	$color = sanitize_hex_color( '{{custom_badge_color}}' );
	printf(
		'<span class="perfectpixel-badge" style="display:inline-block;margin-bottom:.5em;padding:.2em .7em;border-radius:3px;color:#fff;font-size:.85em;background:%s">%s</span>',
		esc_attr( $color ? $color : '#2271b1' ),
		esc_html( $text ? $text : '{{custom_badge_default}}' )
	);
}
